function abilityByName(name,source=null){return CANONICAL_ABILITY_RECORDS.find(a=>a.name===name && (!source||a.source===source));}
function abilitiesForSource(source){return CANONICAL_ABILITY_RECORDS.filter(a=>a.source===source);}
function signKitRecords(sign){return CANONICAL_ABILITY_RECORDS.filter(a=>a.section==="Sign Kits"&&a.source===sign);}
function martialStyleRecords(style){return CANONICAL_ABILITY_RECORDS.filter(a=>a.section==="Martial & Weapon Styles"&&a.source===style);}

  
